// Keep unavailable source links out of the public UI until their repositories
// are restored or replaced. The catalog still preserves the source URL for
// internal maintenance and case-study context.
const unavailableSourceSlugs = new Set([
  "booknbook",
  "digital-products",
  "legal-templates",
  "localcrm",
  "mcp-server",
  "philosophy-archive",
  "religion-compare",
  "solo-empire-cli",
]);

for (const project of allProjects) {
  if (unavailableSourceSlugs.has(project.slug)) {
    project.sourceUnavailable = true;
  }
}

/** The source URL that may be published (UI, JSON-LD, MCP); empty when the source is hidden. */
export function publicSourceUrl(project: Pick<AppProject, "githubUrl" | "sourceUnavailable">): string {
  return project.sourceUnavailable ? "" : project.githubUrl;
}

export function getProjectStatusCounts(projects: readonly AppProject[] = allProjects) {
  return projects.reduce(
    (counts, project) => {
      counts[project.status] += 1;
      return counts;
    },
    { live: 0, wip: 0, archived: 0 },
  );
}
